def calibrated_probabilities(bundle: dict[str, Any], frame: pd.DataFrame) -> np.ndarray:
    scores = bundle["classifier"].decision_function(frame).reshape(-1, 1)
    return bundle["calibrator"].predict_proba(scores)[:, 1]
